style.css:
@-moz-document domain("youtube.com") {
/* FONDO PRINCIPAL */
    body, ytd-app, #page-manager {
        background-color: #fef8f0 !important; /* Amarillo claro muy suave */
    }

    /* BARRA SUPERIOR (HEADER) */
    ytd-masthead {
        background-color: #ffdce8 !important; /* Rosa claro */
    }

    /* BARRA DE BÚSQUEDA */
    ytd-searchbox #container.ytd-searchbox,
    ytd-searchbox #search-icon-legacy.ytd-searchbox {
        background-color: #fff !important;
        border: 1px solid #fecb89 !important; /* Naranja suave */
    }

    /* ICONOS Y TEXTO PRINCIPAL (Hacerlos morado mauve para que resalten) */
    yt-icon.ytd-masthead, yt-icon.ytd-guide-entry-renderer, 
    #guide-section-title.ytd-guide-section-renderer,
    #video-title.ytd-video-renderer,
    #text.ytd-channel-name,
    #metadata-line.ytd-video-meta-block span {
        color: #ac8dae !important; /* Morado Mauve */
    }

    /* ELEMENTOS ACTIVOS / DESTACADOS (Aquí es donde eliminamos el azul) */
    /* Usaremos el Verde Lima para "Aceptar" o "Añadir" y el Naranja para acciones de click */

    /* Menús laterales e iconos de navegación al hacer hover o estar activos */
    ytd-guide-entry-renderer[active] yt-icon.ytd-guide-entry-renderer,
    ytd-guide-entry-renderer[active] .title.ytd-guide-entry-renderer,
    ytd-compact-link-renderer[active] yt-icon.ytd-compact-link-renderer,
    ytd-compact-link-renderer[active] .title.ytd-compact-link-renderer {
        color: #cddc39 !important; /* Verde Lima */
        background-color: #fef8f0 !important; /* Fondo del item */
    }

    /* Menús al hacer hover */
    ytd-guide-entry-renderer:hover, ytd-compact-link-renderer:hover {
        background-color: #fdf2e9 !important; /* Naranja muy pálido para el hover */
    }

    /* BOTONES */
    /* Botones primarios (como "Suscribirse" o "Instalar Estilo" en tu foto) */
    yt-button-renderer.style-primary[is-paper-button],
    yt-button-renderer.style-suggestive[is-paper-button],
    #install-style-button {
        background-color: #cddc39 !important; /* Verde Lima (el azul de la foto) */
        color: #4a148c !important; /* Texto morado oscuro sobre verde */
    }

    /* Botones secundarios */
    yt-button-renderer.style-secondary[is-paper-button] {
        background-color: #fecb89 !important; /* Naranja */
        color: #fff !important;
    }

    /* ENLACES Y TEXTO DE ACCIÓN (como "Compartir") */
    a.yt-simple-endpoint.yt-formatted-string,
    ytd-button-renderer.style-text[is-paper-button] {
        color: #ff8a65 !important; /* Naranja más intenso para llamar la atención */
    }

    /* BARRA DE PROGRESO DEL VIDEO */
    .ytp-scrubber-button, .ytp-play-progress {
        background-color: #ac8dae !important; /* Morado Mauve */
    }

    /* MENÚS DESPLEGABLES (Como el de tu foto) */
    paper-listbox, #contentWrapper.iron-dropdown {
        background-color: #fff !important;
        border: 2px solid #ac8dae !important; /* Borde Mauve */
    }

    paper-item.ytd-menu-service-item-renderer,
    ytd-simple-menu-header-renderer {
        color: #ac8dae !important; /* Texto del menú */
    }

    paper-item:hover {
        background-color: #fdf2e9 !important; /* Naranja pálido */
    }
}
